//! Requests test data (.offrails/guides/testing.md#factories-testsappfactoriesrs): valid params
//! through `validate` + `create`, so a test can't build an invalid row. Generated by `cargo offrails generate resource requests agent:references{agent} title:string description:text category:string location:string budget:money`.

/// Valid RequestParams (unique values numbered), for forms and `request_with`.
pub async fn request_params(
    db: &sea_orm::DatabaseConnection,
    user: &board::models::User,
) -> board::models::request::RequestParams {
    static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(1);
    let n = N.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let agent = super::agent(db, user).await;
    board::models::request::RequestParams {
        agent_id: agent.id.to_string(),
        title: format!("Title {n}"),
        description: format!("Description {n}, long enough to read."),
        category: "research".into(),
        location: format!("Location {n}"),
        budget: "19.99".into(),
    }
}

/// A request owned by `user`, through `RequestParams::validate` + `request::create`.
pub async fn request(
    db: &sea_orm::DatabaseConnection,
    user: &board::models::User,
) -> board::models::request::Model {
    let params = request_params(db, user).await;
    request_with(db, user, params).await
}

/// A request owned by `user` from these params (they must be valid).
pub async fn request_with(
    db: &sea_orm::DatabaseConnection,
    user: &board::models::User,
    params: board::models::request::RequestParams,
) -> board::models::request::Model {
    let new = params.validate().expect("valid request params");
    board::models::request::create(db, user, new)
        .await
        .expect("create request")
}

/// Reads a request back through the entity (tests can't call the model-private `find`).
pub async fn reload_request(
    db: &sea_orm::DatabaseConnection,
    id: i64,
) -> Option<board::models::request::Model> {
    use sea_orm::EntityTrait;
    board::models::request::Entity::find_by_id(id)
        .one(db)
        .await
        .expect("reload request")
}
